{
  "technical_and_design_decisions": [
    "Baseline on Java 17 with Spring Framework 6 / Spring Boot 3, consistent with the specification's statement that Spring Framework 6.0 requires Java 17+.",
    "U1: Implement Azure Event Hubs support as a Spring Cloud Stream binder (producer/consumer factories, provisioning, error handling) built on the official Azure SDK for Java (azure-messaging-eventhubs), plus prebuilt source and sink modules exposing configuration via @ConfigurationProperties.",
    "U2: Integrate with IPython/Jupyter notebooks through the notebook's REST and WebSocket kernel protocol to push/pull stream data, rather than embedding a JVM-based kernel; provide sample notebooks demonstrating real-time computations on XD streams.",
    "U3: Adopt a side-by-side, non-destructive installation/upgrade layout that never overwrites existing install directories or files, and provide a migration utility/script that copies and adapts the previous servers.yml for the new release.",
    "U4: Implement a local/direct binder in Spring Cloud Stream that binds module output/input channels in-JVM via Spring Integration DirectChannel handoff, honoring the existing Binder SPI (including partitioning keys) so no messaging middleware is required.",
    "U5: Build the REST API foundation with Spring MVC/Spring Data REST controllers and HATEOAS representations over a repository SPI, exposing CRUD endpoints for stream definitions and batch job definitions on the admin (xd-admin) server.",
    "U6: Define a ModuleRegistry interface and provide a lightweight stub/in-memory implementation intended for creating mock streams in tests.",
    "U7: Perform a git history-preserving move of spring-cloud-stream-modules into the spring-cloud-stream repository, keeping Maven coordinates stable, and update parent POMs, build plans, and cross-references.",
    "U8: Implement the in-memory stream definition repository as a ConcurrentHashMap-backed implementation of the StreamDefinitionRepository SPI, explicitly non-persistent, selectable via configuration for development use.",
    "Use JUnit 5 for unit tests across all stories, with integration tests per story (Testcontainers or live services where applicable); keep changes backward compatible with existing public APIs."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are effort in workdays (1 workday = 8 focused hours), not elapsed calendar time, and exclude waiting time such as external review turnaround.",
    "The existing Spring XD, Spring Cloud Stream (s-c-s), and Spring Cloud Data (s-c-d) codebases are available, buildable, and familiar to the developer; the estimate covers only the increment described by U1-U8.",
    "An Azure subscription with an Event Hubs namespace is available for developing and running U1 integration tests.",
    "'s-c-s' means Spring Cloud Stream and 's-c-d'/'spring-cloud-data' means Spring Cloud Data (Flow); 'modules' refers to stream source/processor/sink modules.",
    "The IPython integration targets the standard IPython/Jupyter notebook via its REST/WebSocket kernel protocol; no custom kernel or notebook UI development is included.",
    "U3 is limited to preserving prior installation directories/files and enabling copy/reuse of servers.yml; automated migration of persisted runtime data is out of scope.",
    "U5 covers server-side REST APIs only; no web UI/client application work is included.",
    "Documentation effort means developer-facing reference docs, README updates, and migration notes, not full user guides or marketing material.",
    "Each implementation activity includes its unit tests; dedicated integration/system testing and release activities are estimated separately."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment requirements analysis and architecture design",
      "activity_description": "Analyze U1-U8, confirm scope against existing Spring XD/s-c-s/s-c-d codebases, produce the overall design (binder SPI usage, REST API structure, repository SPIs, upgrade layout) and the WBS used for delivery.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Build and CI environment preparation",
      "activity_description": "Set up/update Maven builds, CI plans, and test infrastructure (including Azure credentials handling) needed for the new modules in this increment.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "U1: Azure Event Hubs binder core implementation",
      "activity_description": "Implement the Spring Cloud Stream binder for Azure Event Hubs using the Azure SDK: connection/consumer/producer factories, provisioning, checkpointing/error handling, and configuration properties.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "U1: Event Hubs source and sink modules",
      "activity_description": "Create prebuilt Event Hubs source and sink modules with configuration properties and enable auto-configuration so XD/s-c-s users can read/write Event Hubs data.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "U1: Event Hubs testing and documentation",
      "activity_description": "Unit tests plus integration tests against a live Event Hubs namespace; reference documentation for binder and module options.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "U2: IPython Notebook integration design and prototype",
      "activity_description": "Design the interaction between Spring XD streams and the IPython/Jupyter kernel (REST/WebSocket protocol), and build a working prototype pushing live stream data into a notebook.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "U2: IPython integration implementation and examples",
      "activity_description": "Implement the integration support code and configuration, plus sample notebooks demonstrating interactive real-time computations on XD stream data.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A8",
      "activity_name": "U2: IPython integration tests and documentation",
      "activity_description": "Automated tests for the integration endpoints/handlers and user-facing documentation with setup instructions.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "U3: Non-destructive upgrade and config reuse implementation",
      "activity_description": "Change installation/packaging to a side-by-side layout that preserves older install dirs/files, and implement the utility that copies/adapts the previous servers.yml into the new installation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A10",
      "activity_name": "U3: Upgrade tests and migration guide",
      "activity_description": "Test upgrade scenarios from the previous release (config reuse, preserved files) and write the upgrade/migration guide.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A11",
      "activity_name": "U4: Direct (local) binder implementation",
      "activity_description": "Implement the in-JVM direct binder in Spring Cloud Stream using DirectChannel handoff via the Binder SPI, with partitioning support, enabling middleware-free, low-latency module binding.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A12",
      "activity_name": "U4: Direct binder tests and documentation",
      "activity_description": "Unit/integration tests (including throughput sanity checks and partition routing) and documentation of direct-binding usage and limitations.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A13",
      "activity_name": "U5: Admin domain model and repository SPIs",
      "activity_description": "Define the domain model and repository service-provider interfaces for stream definitions and batch job definitions backing the xd-admin REST layer.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A14",
      "activity_name": "U5: Stream CRUD REST controllers",
      "activity_description": "Implement HATEOAS-based REST controllers for creating, reading, updating, deleting, and listing stream definitions (including validation and error handling).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A15",
      "activity_name": "U5: Batch job CRUD REST controllers and admin wiring",
      "activity_description": "Implement REST endpoints for batch job definition CRUD and wire all controllers into the xd-admin application configuration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A16",
      "activity_name": "U5: REST API tests and documentation",
      "activity_description": "MockMvc/integration tests for all new endpoints and API reference documentation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A17",
      "activity_name": "U6: ModuleRegistry interface and stub implementation",
      "activity_description": "Define the ModuleRegistry API and an in-memory stub implementation, plus tests demonstrating creation of mock streams through the registry APIs.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A18",
      "activity_name": "U7: Move spring-cloud-stream-modules into the s-c repository",
      "activity_description": "Perform a history-preserving move of the modules project, update parent POMs and module lists, keep artifact coordinates stable, update CI plans and fix all cross-project references.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A19",
      "activity_name": "U8: In-memory stream definition repository",
      "activity_description": "Implement a ConcurrentHashMap-backed StreamDefinitionRepository, make it selectable via configuration for development, and add unit tests and brief docs.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A20",
      "activity_name": "End-to-end integration testing and defect fixing",
      "activity_description": "Cross-story system testing (REST API + registry + repositories + direct binding + Event Hubs modules), regression testing against existing XD/s-c-s behavior, and fixing defects found.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A21",
      "activity_name": "Release packaging, release notes, and final documentation",
      "activity_description": "Assemble the distribution, verify the upgraded installation flow, finalize reference docs, and write release notes covering U1-U8.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 78
  }
}

